const SIZE = {
  Small: 'Use the Small scale: 32 px control height, 12 px horizontal padding, 14 px text — for dense desktop UIs.',
  Medium: 'Use the Medium scale: 40 px control height, 16 px horizontal padding, 15–16 px text — the default.',
  Large: 'Use the Large scale: 48 px control height, 20 px horizontal padding, 16 px text — ideal for touch and primary actions.',
};
const THEME = {
  Light: 'Bind fills and text to Light-mode variables; verify text contrast ≥ 4.5:1 on white surfaces.',
  Dark: 'Switch the frame\'s variable mode to Dark; use elevated dark surfaces (not pure black) and re-check contrast for every color pair.',
};
const PLATFORM = {
  Mobile: 'Place inside a 390×844 frame; keep touch targets ≥ 44×44 px and primary actions in the thumb zone.',
  Tablet: 'Place inside an 834×1194 frame on an 8-column grid; consider split views and both orientations.',
  Desktop: 'Place inside a 1440-wide frame on a 12-column grid; add hover and focus-visible states.',
};

let _items = null;
/** Build (once) the full Figma library: base × style × size × theme × platform. */
export function getFigmaItems() {
  if (_items) return _items;
  const out = [];
  for (const [id, name, category, difficulty, what, why, ux, ui, steps, mistake, challenge, styles, mock] of BASES) {
    const sizes = ['Small', 'Medium', 'Large'];
    for (const style of styles) for (const size of sizes) for (const theme of ['Light', 'Dark']) for (const platform of ['Mobile', 'Tablet', 'Desktop']) {
      const vid = `${id}--${style}-${size}-${theme}-${platform}`.toLowerCase().replace(/[^a-z0-9-]+/g, '-');
      out.push({
        id: vid, baseId: id, name: `${name} — ${style}`, variant: { style, size, theme, platform }, category, difficulty,
        what, why, ux, ui,
        steps: [...steps, `Apply the "${style}" style variant and name the property Style=${style}.`, SIZE[size], THEME[theme], PLATFORM[platform]],
        mistake, challenge: `${challenge} (${style}, ${size}, ${theme}, ${platform})`, mock,
        related: BASES.filter((x) => x[2] === category && x[0] !== id).slice(0, 3).map((x) => x[0]),
      });
    }
  }
  _items = out;
  return out;
}
export const FIGMA_BASES = BASES.map(([id, name, category, difficulty]) => ({ id, name, category, difficulty }));
